// Slack Trigger は Events API の event オブジェクトをそのまま出力する
const ev = $input.first().json;

const channel = String(ev.channel ?? '');
const isDm = ev.channel_type === 'im' || channel.startsWith('D');
// ボット自身の投稿(=このワークフローの返信)もイベントとして届くため必ず除外する(無限ループ防止)
const isBot = Boolean(ev.bot_id) || ev.subtype === 'bot_message';
const subtype = ev.subtype ?? null; // message_changed / message_deleted / file_share など

// DM内に <@U0123ABC> 形式のメンション表記が含まれていた場合は除去してLLMに渡す
const text = String(ev.text ?? '').replace(/<@[A-Z0-9]+(\|[^>]*)?>/g, '').trim();

// kind: 'text' = LLMで回答 / 'unsupported' = 「対応していません」 / 'ignore' = 何もしない
// ボットとのDMのみ対応する(チャンネルへの投稿はすべて無視)
let kind = 'ignore';
if (!isBot && isDm) {
  if (subtype === null) kind = text ? 'text' : 'unsupported';
  else if (subtype === 'file_share') kind = 'unsupported';
}

return [{
  json: {
    kind,
    text,
    channel,
    ts: ev.ts,
    // 元の投稿がスレッド内ならそのスレッドへ、それ以外は元の投稿をスレッドの親にして返信
    threadTs: ev.thread_ts ?? ev.ts,
    user: ev.user ?? null,
  },
}];

// LLMの出力(JSON想定)を解析し、Slack Block Kit のブロックを組み立てる。
//   text  → markdown ブロック
//   chart → data_visualization ブロック(Slackネイティブのグラフ。1メッセージ最大2個)
//   table → data_table ブロック(ページング・ソート可能な表)
const raw = String($input.first().json.content ?? '');

// 前後に説明文や ```json フェンスが付いていても、最初の { から最後の } までをJSONとして取り出す
function extractJson(s) {
  const fenced = s.match(/```(?:json)?\s*([\s\S]*?)```/i);
  const candidate = fenced ? fenced[1] : s;
  const start = candidate.indexOf('{');
  const end = candidate.lastIndexOf('}');
  if (start === -1 || end <= start) return null;
  try { return JSON.parse(candidate.slice(start, end + 1)); } catch (e) { return null; }
}

const cut = (s, n) => String(s ?? '').trim().slice(0, n);
const toNum = (v) => typeof v === 'number' ? v : Number(String(v).replace(/[^\d.\-]/g, ''));
const fmtNum = (n) => Number.isInteger(n) ? n.toLocaleString('ja-JP') : n.toLocaleString('ja-JP', { maximumFractionDigits: 2 });

const parsed = extractJson(raw);
// JSONとして解釈できなかった場合は出力全体を本文として扱う(従来どおりの動作)
let text = String((parsed && parsed.text) ?? raw).trim();
if (!text) text = '回答を生成できませんでした。';

const blocks = [{ type: 'markdown', text: text.slice(0, 12000) }];
const notes = [];

// ---------- data_visualization ----------
function buildChart(chart) {
  if (!chart || typeof chart !== 'object') return null;
  const type = ['bar', 'line', 'area', 'pie'].includes(chart.type) ? chart.type : null;
  if (!type) return null;
  const title = cut(chart.title, 50) || 'グラフ';

  // ラベルは20文字以内・最大20件。重複は末尾に番号を付けて一意にする(Slackはカテゴリ名の一致で紐付けるため)
  let labels = Array.isArray(chart.labels) ? chart.labels.map(l => cut(l, 20)).slice(0, 20) : [];
  const seen = new Map();
  labels = labels.map(l => { const c = (seen.get(l) ?? 0) + 1; seen.set(l, c); return c === 1 ? l : cut(l, 17) + `(${c})`; });
  if (labels.length === 0) return null;

  // 単一系列(values)または複数系列(series)を受け付ける
  let series = [];
  if (Array.isArray(chart.series) && chart.series.length) {
    series = chart.series.map((s, i) => ({ name: cut(s?.name, 20) || `系列${i + 1}`, values: Array.isArray(s?.values) ? s.values.map(toNum) : [] }));
  } else if (Array.isArray(chart.values)) {
    series = [{ name: cut(chart.series_name ?? chart.y_label ?? title, 20) || '金額', values: chart.values.map(toNum) }];
  }
  series = series.filter(s => s.values.length >= labels.length && s.values.slice(0, labels.length).every(Number.isFinite)).slice(0, 12);
  if (series.length === 0) return null;
  const names = new Set();
  series.forEach((s, i) => { while (names.has(s.name)) s.name = cut(s.name, 17) + `(${i + 1})`; names.add(s.name); });

  if (type === 'pie') {
    // 円グラフは先頭の系列のみ。値が0以下の項目は描けないので除外、最大12件
    const segments = labels.map((label, i) => ({ label, value: series[0].values[i] })).filter(s => s.value > 0).slice(0, 12);
    if (segments.length === 0) return null;
    return { type: 'data_visualization', title, chart: { type: 'pie', segments } };
  }

  const axis_config = { categories: labels };
  if (chart.x_label) axis_config.x_label = cut(chart.x_label, 50);
  if (chart.y_label) axis_config.y_label = cut(chart.y_label, 50);
  return {
    type: 'data_visualization',
    title,
    chart: {
      type,
      series: series.map(s => ({ name: s.name, data: labels.map((label, i) => ({ label, value: s.values[i] })) })),
      axis_config,
    },
  };
}

// chart は1個または配列で受け付け、Slackの上限(2個)まで追加
const chartInputs = Array.isArray(parsed?.chart) ? parsed.chart : (parsed?.chart ? [parsed.chart] : []);
let chartCount = 0;
for (const c of chartInputs) {
  if (chartCount >= 2) break;
  const b = buildChart(c);
  if (b) { blocks.push(b); chartCount++; }
  else if (c) notes.push('_グラフのデータ形式が不正なため表示できませんでした。_');
}

// ---------- data_table ----------
function buildTable(table) {
  if (!table || typeof table !== 'object') return null;
  const columns = Array.isArray(table.columns) ? table.columns.map(c => cut(c, 100) || '-').slice(0, 20) : [];
  const rowsIn = Array.isArray(table.rows) ? table.rows.slice(0, 200) : [];
  if (columns.length === 0 || rowsIn.length === 0) return null;

  const header = columns.map(c => ({ type: 'raw_text', text: c }));
  const rows = rowsIn.map(r => {
    const cells = Array.isArray(r) ? r : Object.values(r ?? {});
    return columns.map((_, i) => {
      const v = cells[i];
      if (typeof v === 'number' && Number.isFinite(v)) return { type: 'raw_number', value: v, text: fmtNum(v) };
      const s = cut(v, 500);
      return { type: 'raw_text', text: s || '-' };
    });
  });

  // 1メッセージあたりのセル文字数上限(20,000)を超えないように行を減らす
  let total = 0;
  const limited = [];
  for (const r of [header, ...rows]) {
    const len = r.reduce((n, c) => n + String(c.text).length, 0);
    if (total + len > 19000) break;
    total += len;
    limited.push(r);
  }
  if (limited.length < 2) return null;
  if (limited.length < rows.length + 1) notes.push(`_表が長いため先頭 **${limited.length - 1}** 件のみ表示しています。_`);

  return {
    type: 'data_table',
    caption: cut(table.caption, 100) || '一覧',
    page_size: Math.min(10, limited.length - 1),
    rows: limited,
  };
}

const tableBlock = buildTable(parsed?.table);
if (tableBlock) blocks.push(tableBlock);
else if (parsed?.table) notes.push('_表のデータ形式が不正なため表示できませんでした。_');

if (notes.length) blocks.push({ type: 'context', elements: [{ type: 'mrkdwn', text: notes.join('\n') }] });

// 通知欄などに表示されるフォールバック用テキスト(装飾を落とした先頭行)
const firstLine = text.replace(/[*_`#>]/g, '').split('\n').map(s => s.trim()).filter(Boolean)[0] || '回答';

return [{ json: { text, fallbackText: firstLine.slice(0, 200), blocks } }];

